/**
 * badgeUtils.js
 * Utilities for generating and inserting badge blocks in README.md files.
 */

const fs = require('fs');
const path = require('path');

/**
 * Generate badge markdown for all workflows in .github/workflows/
 */
function generateWorkflowBadges(repo, branch = 'main', format = 'stacked') {
    const workflowsDir = path.join('.github', 'workflows');
    if (!fs.existsSync(workflowsDir)) {
        return [];
    }
    const badges = [];
    fs.readdirSync(workflowsDir).forEach((file) => {
        if (file.endsWith('.yml') || file.endsWith('.yaml')) {
            const workflowName = file.replace(/\.(yml|yaml)$/, '');
            const badgeUrl = `https://github.com/${repo}/actions/workflows/${file}/badge.svg?branch=${branch}`;
            const workflowUrl = `https://github.com/${repo}/actions/workflows/${file}`;
            badges.push(`[![${workflowName}](${badgeUrl})](${workflowUrl})`);
        }
    });
    if (badges.length === 0) {
        return [];
    }
    if (format === 'inline') {
        return [badges.join(' ')];
    }
    return badges;
}

/**
 * Insert or update badge block in README.md between <!-- BADGES-START --> and <!-- BADGES-END -->
 */
function updateReadmeBadges(readmeFile, badges) {
    const badgeStart = '<!-- BADGES-START -->';
    const badgeEnd = '<!-- BADGES-END -->';
    let content = fs.readFileSync(readmeFile, 'utf-8');
    const badgeBlock = [badgeStart, ...badges, badgeEnd].join('\n');
    if (content.includes(badgeStart) && content.includes(badgeEnd)) {
        // Replace existing block
        content = content.replace(
            new RegExp(`${badgeStart}[\\s\\S]*?${badgeEnd}`, 'm'),
            badgeBlock
        );
    } else {
        // Insert after first header
        content = content.replace(/^(# .+\n)/, `$1${badgeBlock}\n`);
    }
    fs.writeFileSync(readmeFile, content);
}

module.exports = {
    generateWorkflowBadges,
    updateReadmeBadges,
};

/**
 * @fileoverview Builds a label alias mapping from labels.yml.
 * @module build-label-alias-map
 */

const fs = require('fs');
const yaml = require('js-yaml');

/**
 * Reads labels.yml and returns an alias map for label canonicalization.
 * @param {string} [labelsYmlPath='.github/labels.yml'] - Path to labels YAML.
 * @returns {Object} aliasMap - Mapping of alias to canonical label.
 */
function buildLabelAliasMap(labelsYmlPath = '.github/labels.yml') {
    const yml = fs.readFileSync(labelsYmlPath, 'utf8');
    const labelsData = yaml.load(yml);
    const aliasMap = {};
    labelsData.forEach((label) => {
        if (typeof label === 'object' && Array.isArray(label.aliases)) {
            label.aliases.forEach((alias) => {
                aliasMap[alias] = label.name;
            });
        }
    });
    return aliasMap;
}

module.exports = {
    buildLabelAliasMap,
};

/**
 * @fileoverview Generates a Markdown audit report comparing current and canonical labels.
 * @module build-labeling-report
 */

const { labelsToMarkdownTable, diffLabels } = require('./label-utils');

/**
 * Builds a Markdown-formatted audit report for labels on an issue/PR.
 * @param {string[]} currentLabels - Array of current label names.
 * @param {string[]} canonicalLabels - Array of canonical label names.
 * @returns {string} Markdown string summarizing label audit.
 */
function buildLabelingReport(currentLabels, canonicalLabels) {
    const { missing, extra } = diffLabels(currentLabels, canonicalLabels);
    let report = '## Label Audit Report\n';
    report += '\n**Current Labels:**\n' + labelsToMarkdownTable(currentLabels);
    report +=
        '\n**Expected Canonical Labels:**\n' +
        labelsToMarkdownTable(canonicalLabels);
    if (missing.length)
        report +=
            '\n**Missing Canonical Labels:**\n' +
            labelsToMarkdownTable(missing);
    if (extra.length)
        report +=
            '\n**Extra (Non-canonical) Labels:**\n' +
            labelsToMarkdownTable(extra);
    return report;
}

module.exports = { buildLabelingReport };

/**
 * changelogUtils.js
 * Utilities for validating and updating CHANGELOG.md files.
 */

const fs = require('fs');

/**
 * Validate that all [Unreleased] changelog entries have a PR/Issue/Commit link.
 * Returns array of lines missing a link.
 */
function validateChangelogLinks(changelogPath = 'CHANGELOG.md') {
    if (!fs.existsSync(changelogPath)) {
        return [];
    }
    const content = fs.readFileSync(changelogPath, 'utf-8');
    // Extract [Unreleased] block
    const match = content.match(/^## \[Unreleased\][\s\S]*?(?=^## \[|$)/m);
    if (!match) {
        return [];
    }
    const unreleasedBlock = match[0];
    const lines = unreleasedBlock.split('\n');
    const missingLinks = [];
    for (const line of lines) {
        if (
            /^-/.test(line) &&
            !/(#[0-9]+|\[.*\]\(https:\/\/github.com\/.*\/(pull|issues|commit)\/[^)]+\))/.test(
                line
            )
        ) {
            missingLinks.push(line);
        }
    }
    return missingLinks;
}

module.exports = {
    validateChangelogLinks,
};

#!/usr/bin/env node
// check-template-labels.js
// Fails if any label in issue templates or issue-types.yml is not in labels.yml

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

const LABELS_FILE = path.resolve(__dirname, '../../.github/labels.yml');
const ISSUE_TYPES_FILE = path.resolve(
    __dirname,
    '../../.github/issue-types.yml'
);
const ISSUE_TEMPLATE_DIR = path.resolve(
    __dirname,
    '../../.github/ISSUE_TEMPLATE'
);

function loadYaml(file) {
    return yaml.load(fs.readFileSync(file, 'utf8'));
}

function getCanonicalLabels() {
    const labels = loadYaml(LABELS_FILE);
    return new Set(labels.map((l) => l.name));
}

function getIssueTypeLabels() {
    const types = loadYaml(ISSUE_TYPES_FILE);
    const labels = new Set();
    for (const type of types) {
        if (type.label) labels.add(type.label);
        if (type.labels && Array.isArray(type.labels)) {
            for (const l of type.labels) labels.add(l);
        }
    }
    return labels;
}

function getTemplateLabels() {
    const files = fs
        .readdirSync(ISSUE_TEMPLATE_DIR)
        .filter((f) => f.endsWith('.md'));
    const labelRegex = /labels?:\s*\[([^\]]+)\]|labels?:\s*([^\n]+)/gi;
    const labels = new Set();
    for (const file of files) {
        const content = fs.readFileSync(
            path.join(ISSUE_TEMPLATE_DIR, file),
            'utf8'
        );
        let match;
        while ((match = labelRegex.exec(content))) {
            let found = match[1] || match[2];
            if (found) {
                found
                    .split(',')
                    .map((l) => l.replace(/['"\[\]]/g, '').trim())
                    .forEach((l) => {
                        if (l) labels.add(l);
                    });
            }
        }
    }
    return labels;
}

function main() {
    const canonical = getCanonicalLabels();
    const issueTypeLabels = getIssueTypeLabels();
    const templateLabels = getTemplateLabels();
    const all = new Set([...issueTypeLabels, ...templateLabels]);
    const unknown = [...all].filter((l) => l && !canonical.has(l));
    if (unknown.length) {
        console.error('Unknown labels found in templates or issue-types.yml:');
        for (const l of unknown) console.error(`  - ${l}`);
        process.exit(1);
    } else {
        console.log('All template and type labels are valid.');
    }
}

main();

#!/usr/bin/env node
/**
 * UK English normalisation script.
 *
 * Converts common US spellings to UK variants in markdown files while:
 *  - Skipping code fences, inline code, and frontmatter keys
 *  - Avoiding changes inside JSON, JS, or CSS fenced blocks
 *  - Preserving case (Colour vs colour)
 *  - Dry-run by default (no file writes) unless --apply supplied
 *
 * Usage:
 *   node scripts/en-gb-normalise.js              # dry run summary
 *   node scripts/en-gb-normalise.js --apply      # apply in-place edits
 *   node scripts/en-gb-normalise.js path/thing.md other/*.md
 */

const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const APPLY = args.includes('--apply');
const EXPLICIT_FILES = args.filter((a) => !a.startsWith('--'));

// Basic mapping (extend cautiously). Order matters (longer first to prevent partial overlaps).
// NOTE: 'color'/'colors' intentionally excluded because JSON schemas (theme.json), CSS properties,
// and block support keys must retain US spelling. Narrative prose may use "colour", but automation
// should not transform these tokens to avoid corrupting examples or misleading users copying code.
const MAP = [
    ['behavior', 'behaviour'],
    ['behaviors', 'behaviours'],
    ['organize', 'organise'],
    ['organizing', 'organising'],
    ['optimization', 'optimisation'],
    ['optimize', 'optimise'],
    ['optimized', 'optimised'],
    ['license', 'licence'],
    ['customization', 'customisation'],
    ['customize', 'customise'],
    ['analyze', 'analyse'],
    ['analyzing', 'analysing'],
    ['initialize', 'initialise'],
    ['initialization', 'initialisation'],
];

// Exceptions: tokens / identifiers we must not touch (exact match case-insensitive tests in code spans or JSON keys not necessary due to skip logic, but add safety net for plain text contexts).
const EXCEPT_REGEX =
    /\b(ColorPicker|BehaviorSubject|useColorMode|licenseKey)\b/i;

function listMarkdownFiles(dir) {
    if (!fs.existsSync(dir)) return [];
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    return entries.flatMap((e) => {
        const res = path.join(dir, e.name);
        if (e.isDirectory()) return listMarkdownFiles(res);
        if (e.isFile() && res.endsWith('.md')) return [res];
        return [];
    });
}

function applyMappings(segment) {
    return MAP.reduce((acc, [us, uk]) => {
        return acc.replace(new RegExp(`\\b${us}\\b`, 'gi'), (match) => {
            if (EXCEPT_REGEX.test(match)) return match; // skip exceptions
            // Preserve case: all caps, capitalised, or lower
            if (match === match.toUpperCase()) return uk.toUpperCase();
            if (match[0] === match[0].toUpperCase())
                return uk.charAt(0).toUpperCase() + uk.slice(1);
            return uk;
        });
    }, segment);
}

function processFile(file) {
    const original = fs.readFileSync(file, 'utf8');
    const lines = original.split(/\n/);

    let inFence = false;
    let fenceLang = '';
    let inFrontMatter = false;
    let changed = false;

    const processed = lines
        .map((line, idx) => {
            // Frontmatter toggling
            if (idx === 0 && line.trim() === '---') {
                inFrontMatter = true;
                return line; // do not transform frontmatter keys/values
            }
            if (inFrontMatter) {
                if (line.trim() === '---') inFrontMatter = false;
                return line;
            }

            // Code fence detection
            const fenceMatch = line.match(/^```(.*)$/);
            if (fenceMatch) {
                if (!inFence) {
                    inFence = true;
                    fenceLang = fenceMatch[1].trim();
                } else {
                    inFence = false;
                    fenceLang = '';
                }
                return line; // do not transform fence markers or contents
            }

            if (inFence) return line; // skip content inside fenced code blocks entirely

            // Skip inline code spans by splitting on backticks and only transforming even index segments
            if (line.includes('`')) {
                const parts = line.split(/(`[^`]*`)/); // keep delimiters
                const transformed = parts.map((part) => {
                    if (part.startsWith('`') && part.endsWith('`')) return part; // code span
                    const newPart = applyMappings(part);
                    if (newPart !== part) changed = true;
                    return newPart;
                });
                return transformed.join('');
            }

            const newLine = applyMappings(line);
            if (newLine !== line) changed = true;
            return newLine;
        })
        .join('\n');

    if (changed) {
        if (APPLY) {
            fs.writeFileSync(file, processed, 'utf8');
        }
    }
    return { file, changed };
}

function run() {
    const targets = EXPLICIT_FILES.length
        ? EXPLICIT_FILES
        : listMarkdownFiles(process.cwd());
    const results = targets.map(processFile);
    const changed = results.filter((r) => r.changed).map((r) => r.file);
    if (!APPLY) {
        console.log(
            'Dry run: files that would change (run with --apply to write):'
        );
        changed.forEach((f) => console.log('  ' + f));
    } else {
        console.log('Applied UK English normalisation to files:');
        changed.forEach((f) => console.log('  ' + f));
    }
    console.log(`Total changed: ${changed.length}`);
}

run();

