 */

/**
 * Suggest labels from content using heuristics (regex, keywords, etc.)
 * @param {Object} item - { title, body }
 * @param {Object} aliasMap - for canonicalization
 * @returns {string[]} Array of suggested canonical label strings
 */
function suggestLabelsFromContent(item, aliasMap) {
    const heuristics = {
        'type:bug': [
            /\b(bug|error|issue|broken|fail|crash|exception|not working|fix)\b/i,
        ],
        'type:feature': [
            /\b(feature|enhancement|improvement|add|new|request|proposal|suggestion|create|implement|build|develop)\b/i,
        ],
        'type:documentation': [
            /\b(documentation|docs|readme|guide|tutorial|document|explain|clarify|describe)\b/i,
        ],
        'type:refactor': [
            /\b(refactor|restructure|reorganize|cleanup|optimize|improve|simplify|modernize)\b/i,
        ],
        'priority:high': [
            /\b(urgent|critical|high priority|asap|blocking|production|live|customer|client)\b/i,
        ],
        'priority:low': [
            /\b(low priority|nice to have|minor|cosmetic|polish)\b/i,
        ],
        'area:security': [
            /\b(security|vulnerability|exploit|attack|auth|authentication|permission|access|credential|token|password)\b/i,
        ],
        'area:performance': [
            /\b(performance|speed|slow|optimization|bottleneck|memory|cpu|latency|load time)\b/i,
        ],
    };
    const labels = new Set();
    const content = `${item.title || ''} ${item.body || ''}`.toLowerCase();
    for (const [label, patterns] of Object.entries(heuristics)) {
        for (const pattern of patterns) {
            if (pattern.test(content) && aliasMap[label]) {
                labels.add(aliasMap[label]);
                break;
            }
        }
    }
    return Array.from(labels);
}

module.exports = {
    suggestLabelsFromContent,
};

/**
 * @fileoverview Utilities for canonical label lookup and alias mapping.
 * @module label-lookup
 */

const fs = require('fs');
const yaml = require('js-yaml');

/**
 * Loads and parses canonical labels from a YAML file.
 * @param {string} [labelsYmlPath='.github/labels.yml'] - Path to labels YAML.
 * @returns {Set<string>} Set of canonical label names.
 */
function fetchCanonicalLabels(labelsYmlPath = '.github/labels.yml') {
    const yml = fs.readFileSync(labelsYmlPath, 'utf8');
    const labelsData = yaml.load(yml);
    return new Set(labelsData.map((l) => (typeof l === 'string' ? l : l.name)));
}

/**
 * Builds a mapping of label aliases to their canonical label name.
 * @param {Array<Object>} labelsData - Parsed label definitions from labels.yml.
 * @returns {Object} aliasMap - Maps alias string to canonical label.
 */
function buildLabelAliasMap(labelsData) {
    const aliasMap = {};
    if (!labelsData) return aliasMap;
    labelsData.forEach((label) => {
        if (
            label &&
            typeof label === 'object' &&
            Array.isArray(label.aliases)
        ) {
            label.aliases.forEach((alias) => {
                aliasMap[alias] = label.name;
            });
        }
    });
    return aliasMap;
}

/**
 * Finds the canonical label for a given label or alias.
 * @param {string} label - The label or alias to look up.
 * @param {Object} aliasMap - Alias mapping object.
 * @param {Set<string>} canonicalSet - Set of canonical label names.
 * @returns {string|null} Canonical label name or null if not found.
 */
function findStandardLabel(label, aliasMap, canonicalSet) {
    if (canonicalSet.has(label)) return label;
    if (aliasMap && aliasMap[label]) return aliasMap[label];
    return null;
}

module.exports = {
    fetchCanonicalLabels,
    buildLabelAliasMap,
    findStandardLabel,
};

