const { execSync } = require('child_process');
const fs = require('fs');
const DRY = process.env.DRY_RUN === 'true';
function hasScript(n) {
    try {
        const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
        return pkg.scripts && pkg.scripts[n];
    } catch {
        return false;
    }
}
function run(c) {
    console.log(`$ ${c}`);
